const pptxgen = require("pptxgenjs");

// ============================================================
// Color Palette: Forest & Moss (energy/nature themed)
// Primary: 2C5F2D (forest green), Secondary: 97BC62 (moss), Accent: F5F5F5 (cream)
// Additional: 1A3A1B (dark forest), E8F5E9 (light green bg)
// ============================================================
const C = {
  primary: "2C5F2D",
  secondary: "97BC62",
  accent: "F5F5F5",
  dark: "1A3A1B",
  light: "E8F5E9",
  white: "FFFFFF",
  black: "1E1E1E",
  gray: "6B7280",
  lightGray: "F3F4F6",
  chartHydro: "065A82",
  chartWind: "1C7293",
  chartSolar: "97BC62",
  chartOther: "B85042"
};

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Global Renewable Energy in 2025: How Far Have We Come?";
pres.author = "Our World in Data";
pres.subject = "Global Renewable Energy Trends";

// ============================================================
// Helper functions
// ============================================================
function addFooter(slide, text) {
  slide.addText(text, {
    x: 0.4, y: 5.35, w: 9.2, h: 0.2,
    fontSize: 9, fontFace: "Calibri", color: C.gray,
    align: "left", valign: "middle"
  });
}

function addSlideNumber(slide, num) {
  slide.addText(String(num), {
    x: 9.4, y: 5.35, w: 0.2, h: 0.2,
    fontSize: 9, fontFace: "Calibri", color: C.gray,
    align: "right", valign: "middle"
  });
}

// ============================================================
// SLIDE 1: Title Slide
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.dark };

  // Decorative accent bar at top
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.secondary }
  });

  // Title
  slide.addText("Global Renewable Energy in 2025", {
    x: 0.6, y: 1.6, w: 8.8, h: 1.0,
    fontSize: 40, fontFace: "Arial Black", color: C.white,
    bold: true, align: "center", valign: "middle"
  });

  // Subtitle
  slide.addText("How Far Have We Come?", {
    x: 0.6, y: 2.5, w: 8.8, h: 0.6,
    fontSize: 28, fontFace: "Arial", color: C.secondary,
    align: "center", valign: "middle"
  });

  // Scope line
  slide.addText("A data-driven overview of renewable energy trends across primary energy and electricity", {
    x: 1.0, y: 3.3, w: 8.0, h: 0.5,
    fontSize: 14, fontFace: "Calibri", color: C.light,
    align: "center", valign: "middle"
  });

  // Source attribution
  slide.addText("Source: Our World in Data – Renewable Energy | Authors: Hannah Ritchie, Max Roser, Pablo Rosado", {
    x: 0.6, y: 4.6, w: 8.8, h: 0.3,
    fontSize: 10, fontFace: "Calibri", color: C.gray,
    align: "center", valign: "middle"
  });

  addSlideNumber(slide, 1);
}

// ============================================================
// SLIDE 2: Fossil Fuel Dominance Context
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: C.primary }
  });

  slide.addText("75% of Global GHG Emissions Still Come from Fossil Fuels", {
    x: 0.5, y: 0.3, w: 9.0, h: 0.7,
    fontSize: 32, fontFace: "Arial Black", color: C.dark,
    bold: true, align: "left", valign: "middle"
  });

  // Three stat cards
  const cardY = 1.2;
  const cardW = 2.8;
  const cardH = 2.2;
  const gap = 0.3;
  const startX = 0.5;

  // Card 1: 75%
  slide.addShape(pres.shapes.RECTANGLE, {
    x: startX, y: cardY, w: cardW, h: cardH,
    fill: { color: C.light }, line: { color: C.secondary, width: 1 }
  });
  slide.addText("75%", {
    x: startX, y: cardY + 0.2, w: cardW, h: 0.8,
    fontSize: 52, fontFace: "Arial Black", color: C.primary,
    bold: true, align: "center", valign: "middle"
  });
  slide.addText("of global greenhouse\ngas emissions from\nfossil fuel burning", {
    x: startX + 0.1, y: cardY + 1.0, w: cardW - 0.2, h: 1.0,
    fontSize: 13, fontFace: "Calibri", color: C.black,
    align: "center", valign: "top"
  });

  // Card 2: 5M+
  slide.addShape(pres.shapes.RECTANGLE, {
    x: startX + cardW + gap, y: cardY, w: cardW, h: cardH,
    fill: { color: C.light }, line: { color: C.secondary, width: 1 }
  });
  slide.addText("5M+", {
    x: startX + cardW + gap, y: cardY + 0.2, w: cardW, h: 0.8,
    fontSize: 52, fontFace: "Arial Black", color: C.primary,
    bold: true, align: "center", valign: "middle"
  });
  slide.addText("premature deaths\nannually from air\npollution", {
    x: startX + cardW + gap + 0.1, y: cardY + 1.0, w: cardW - 0.2, h: 1.0,
    fontSize: 13, fontFace: "Calibri", color: C.black,
    align: "center", valign: "top"
  });

  // Card 3: Industrial Revolution
  slide.addShape(pres.shapes.RECTANGLE, {
    x: startX + 2 * (cardW + gap), y: cardY, w: cardW, h: cardH,
    fill: { color: C.light }, line: { color: C.secondary, width: 1 }
  });
  slide.addText("Since the\nIndustrial\nRevolution", {
    x: startX + 2 * (cardW + gap), y: cardY + 0.2, w: cardW, h: 0.8,
    fontSize: 22, fontFace: "Arial Black", color: C.primary,
    bold: true, align: "center", valign: "middle"
  });
  slide.addText("fossil fuels have\ndominated energy\nsystems worldwide", {
    x: startX + 2 * (cardW + gap) + 0.1, y: cardY + 1.0, w: cardW - 0.2, h: 1.0,
    fontSize: 13, fontFace: "Calibri", color: C.black,
    align: "center", valign: "top"
  });

  // Bottom context text
  slide.addText("To reduce CO₂ emissions and air pollution, the world must rapidly shift toward low-carbon energy sources — nuclear and renewable technologies.", {
    x: 0.5, y: 3.7, w: 9.0, h: 0.6,
    fontSize: 15, fontFace: "Calibri", color: C.black,
    align: "left", valign: "middle"
  });

  // Definition box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.4, w: 9.0, h: 0.7,
    fill: { color: C.lightGray }, line: { color: C.gray, width: 0.5 }
  });
  slide.addText("Renewable energy includes solar, wind, hydropower, geothermal, bioenergy, wave, and tidal sources. Traditional biomass is typically excluded from modern renewable statistics.", {
    x: 0.6, y: 4.45, w: 8.8, h: 0.6,
    fontSize: 11, fontFace: "Calibri", color: C.gray,
    align: "left", valign: "middle"
  });

  addFooter(slide, "Source: Our World in Data – Renewable Energy");
  addSlideNumber(slide, 2);
}

// ============================================================
// SLIDE 3: Renewables in Primary Energy (~14%)
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: C.primary }
  });

  slide.addText("Renewables Now Supply ~14% of Global Primary Energy", {
    x: 0.5, y: 0.25, w: 9.0, h: 0.7,
    fontSize: 32, fontFace: "Arial Black", color: C.dark,
    bold: true, align: "left", valign: "middle"
  });

  // Left: big stat + context
  slide.addText("~14%", {
    x: 0.5, y: 1.1, w: 3.5, h: 1.0,
    fontSize: 64, fontFace: "Arial Black", color: C.primary,
    bold: true, align: "left", valign: "middle"
  });
  slide.addText("of the world's primary energy now comes from renewable technologies (2024 data, substitution method)", {
    x: 0.5, y: 2.1, w: 3.5, h: 1.0,
    fontSize: 13, fontFace: "Calibri", color: C.black,
    align: "left", valign: "top"
  });

  slide.addText("Primary energy encompasses electricity, transport, and heating combined. Because transport and heating are harder to decarbonize, the renewable share in total energy is lower than in electricity alone.", {
    x: 0.5, y: 3.2, w: 3.5, h: 1.4,
    fontSize: 12, fontFace: "Calibri", color: C.gray,
    align: "left", valign: "top"
  });

  // Right: map image
  slide.addImage({
    path: "/app/benchmark/assets/figure_2.jpg",
    x: 4.3, y: 1.0, w: 5.2, h: 3.8,
    sizing: { type: "contain", w: 5.2, h: 3.8 }
  });

  slide.addText("Share of primary energy from renewables by country, 2024", {
    x: 4.3, y: 4.85, w: 5.2, h: 0.25,
    fontSize: 10, fontFace: "Calibri", color: C.gray,
    align: "center", valign: "middle"
  });

  // Regional leaders callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.5, w: 3.5, h: 0.6,
    fill: { color: C.light }
  });
  slide.addText("Leaders: Norway, Brazil, New Zealand > 60% | Middle East & parts of Asia < 5%", {
    x: 0.6, y: 4.5, w: 3.3, h: 0.6,
    fontSize: 11, fontFace: "Calibri", color: C.dark,
    align: "left", valign: "middle"
  });

  addFooter(slide, "Source: Our World in Data – Renewable Energy (Ember 2026; Energy Institute 2025)");
  addSlideNumber(slide, 3);
}

// ============================================================
// SLIDE 4: Renewable Electricity Generation Growth
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: C.primary }
  });

  slide.addText("Renewable Electricity Generation Is Growing Rapidly, Led by Wind and Solar", {
    x: 0.5, y: 0.25, w: 9.0, h: 0.7,
    fontSize: 28, fontFace: "Arial Black", color: C.dark,
    bold: true, align: "left", valign: "middle"
  });

  // Bar chart: generation by technology
  slide.addChart(pres.charts.BAR, [{
    name: "Generation (TWh)",
    labels: ["Hydropower", "Wind", "Solar", "Other renewables"],
    values: [4500, 2400, 2000, 700]
  }], {
    x: 0.5, y: 1.1, w: 5.5, h: 3.6,
    barDir: "col",
    chartColors: [C.chartHydro, C.chartWind, C.chartSolar, C.chartOther],
    chartArea: { fill: { color: C.white }, roundedCorners: true },
    catAxisLabelColor: C.black,
    valAxisLabelColor: C.gray,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.black,
    showLegend: false,
    showTitle: true,
    title: "Global Renewable Electricity Generation by Technology (2024, TWh)",
    titleFontSize: 12,
    titleColor: C.dark
  });

  // Right side: data table + insight
  const tableX = 6.3;
  const tableY = 1.3;
  slide.addTable([
    [
      { text: "Technology", options: { fill: { color: C.primary }, color: C.white, bold: true } },
      { text: "Generation (TWh)", options: { fill: { color: C.primary }, color: C.white, bold: true } },
      { text: "Share", options: { fill: { color: C.primary }, color: C.white, bold: true } }
    ],
    ["Hydropower", "~4,500", "~47%"],
    ["Wind", "~2,400", "~25%"],
    ["Solar", "~2,000", "~21%"],
    ["Other renewables", "~700", "~7%"]
  ], {
    x: tableX, y: tableY, w: 3.2, h: 1.8,
    border: { pt: 0.5, color: "CCCCCC" },
    fill: { color: C.white },
    fontSize: 12, fontFace: "Calibri",
    color: C.black,
    colW: [1.4, 1.0, 0.8],
    align: "center",
    valign: "middle"
  });

  // Insight box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: tableX, y: 3.4, w: 3.2, h: 1.4,
    fill: { color: C.light }
  });
  slide.addText("Wind and solar combined now nearly match hydropower's output and are growing much faster. Solar has seen dramatic growth since ~2010, driven by falling costs and policy support.", {
    x: tableX + 0.1, y: 3.45, w: 3.0, h: 1.3,
    fontSize: 12, fontFace: "Calibri", color: C.dark,
    align: "left", valign: "top"
  });

  addFooter(slide, "Source: Our World in Data – Renewable Energy (Ember 2026; Energy Institute 2025)");
  addSlideNumber(slide, 4);
}

// ============================================================
// SLIDE 5: Electricity Mix ~One-Third Renewable
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: C.primary }
  });

  slide.addText("Almost One-Third of Global Electricity Now Comes from Renewables", {
    x: 0.5, y: 0.25, w: 9.0, h: 0.7,
    fontSize: 28, fontFace: "Arial Black", color: C.dark,
    bold: true, align: "left", valign: "middle"
  });

  // Map on left
  slide.addImage({
    path: "/app/benchmark/assets/figure_1.jpg",
    x: 0.5, y: 1.1, w: 5.0, h: 3.6,
    sizing: { type: "contain", w: 5.0, h: 3.6 }
  });
  slide.addText("Share of electricity from renewables by country, 2025", {
    x: 0.5, y: 4.75, w: 5.0, h: 0.2,
    fontSize: 10, fontFace: "Calibri", color: C.gray,
    align: "center", valign: "middle"
  });

  // Data table on right
  slide.addText("Renewable Share of Electricity by Country/Region", {
    x: 5.8, y: 1.0, w: 3.7, h: 0.3,
    fontSize: 13, fontFace: "Arial Black", color: C.dark,
    bold: true, align: "left", valign: "middle"
  });

  slide.addTable([
    [
      { text: "Country / Region", options: { fill: { color: C.primary }, color: C.white, bold: true } },
      { text: "Renewable Share", options: { fill: { color: C.primary }, color: C.white, bold: true } }
    ],
    ["Norway", "~98%"],
    ["Brazil", "~85%"],
    ["Canada", "~65%"],
    ["China", "~35%"],
    ["India", "~25%"],
    ["Saudi Arabia", "<2%"]
  ], {
    x: 5.8, y: 1.4, w: 3.7, h: 2.4,
    border: { pt: 0.5, color: "CCCCCC" },
    fill: { color: C.white },
    fontSize: 12, fontFace: "Calibri",
    color: C.black,
    colW: [2.2, 1.5],
    align: "center",
    valign: "middle"
  });

  // World average callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.8, y: 4.1, w: 3.7, h: 0.7,
    fill: { color: C.light }
  });
  slide.addText("World average: ~30% | Several African and Middle Eastern countries remain below 10%", {
    x: 5.9, y: 4.1, w: 3.5, h: 0.7,
    fontSize: 11, fontFace: "Calibri", color: C.dark,
    align: "left", valign: "middle"
  });

  addFooter(slide, "Source: Our World in Data – Renewable Energy (Ember 2026; Energy Institute 2025)");
  addSlideNumber(slide, 5);
}

// ============================================================
// SLIDE 6: Hydropower Still Largest Source
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: C.primary }
  });

  slide.addText("Hydropower Remains the Largest Renewable Source at ~50% of Generation", {
    x: 0.5, y: 0.25, w: 9.0, h: 0.7,
    fontSize: 28, fontFace: "Arial Black", color: C.dark,
    bold: true, align: "left", valign: "middle"
  });

  // Big stat left
  slide.addText("~50%", {
    x: 0.5, y: 1.3, w: 3.0, h: 1.0,
    fontSize: 60, fontFace: "Arial Black", color: C.chartHydro,
    bold: true, align: "left", valign: "middle"
  });
  slide.addText("of all renewable electricity comes from hydropower", {
    x: 0.5, y: 2.3, w: 3.0, h: 0.6,
    fontSize: 14, fontFace: "Calibri", color: C.black,
    align: "left", valign: "top"
  });

  slide.addText("Hydropower has been generating electricity at scale for over a century. Top producers include China, Brazil, and Canada.", {
    x: 0.5, y: 3.1, w: 3.0, h: 1.0,
    fontSize: 13, fontFace: "Calibri", color: C.gray,
    align: "left", valign: "top"
  });

  // Map right
  slide.addImage({
    path: "/app/benchmark/assets/figure_6.jpg",
    x: 3.9, y: 1.1, w: 5.6, h: 3.8,
    sizing: { type: "contain", w: 5.6, h: 3.8 }
  });
  slide.addText("Hydropower generation by country, 2025", {
    x: 3.9, y: 4.95, w: 5.6, h: 0.2,
    fontSize: 10, fontFace: "Calibri", color: C.gray,
    align: "center", valign: "middle"
  });

  addFooter(slide, "Source: Our World in Data – Renewable Energy");
  addSlideNumber(slide, 6);
}

// ============================================================
// SLIDE 7: Wind and Solar Fastest Growing
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: C.primary }
  });

  slide.addText("Wind and Solar Are the Fastest-Growing Energy Technologies in History", {
    x: 0.5, y: 0.25, w: 9.0, h: 0.7,
    fontSize: 26, fontFace: "Arial Black", color: C.dark,
    bold: true, align: "left", valign: "middle"
  });

  // Wind map on left
  slide.addImage({
    path: "/app/benchmark/assets/figure_8.jpg",
    x: 0.5, y: 1.1, w: 4.8, h: 3.4,
    sizing: { type: "contain", w: 4.8, h: 3.4 }
  });
  slide.addText("Wind power generation by country, 2025", {
    x: 0.5, y: 4.55, w: 4.8, h: 0.2,
    fontSize: 10, fontFace: "Calibri", color: C.gray,
    align: "center", valign: "middle"
  });

  // Comparison cards on right
  const cardX = 5.6;
  const cardW = 4.0;

  // Wind card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 1.1, w: cardW, h: 1.5,
    fill: { color: C.light }
  });
  slide.addText("WIND", {
    x: cardX + 0.1, y: 1.15, w: cardW - 0.2, h: 0.3,
    fontSize: 14, fontFace: "Arial Black", color: C.chartWind,
    bold: true, align: "left", valign: "middle"
  });
  slide.addText("~2,400 TWh", {
    x: cardX + 0.1, y: 1.5, w: cardW - 0.2, h: 0.4,
    fontSize: 28, fontFace: "Arial Black", color: C.chartWind,
    bold: true, align: "left", valign: "middle"
  });
  slide.addText("~25% of renewable electricity | Major in Europe, China, and the United States | Includes onshore and offshore", {
    x: cardX + 0.1, y: 1.9, w: cardW - 0.2, h: 0.6,
    fontSize: 11, fontFace: "Calibri", color: C.black,
    align: "left", valign: "top"
  });

  // Solar card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 2.8, w: cardW, h: 1.5,
    fill: { color: C.light }
  });
  slide.addText("SOLAR", {
    x: cardX + 0.1, y: 2.85, w: cardW - 0.2, h: 0.3,
    fontSize: 14, fontFace: "Arial Black", color: C.chartSolar,
    bold: true, align: "left", valign: "middle"
  });
  slide.addText("~2,000 TWh", {
    x: cardX + 0.1, y: 3.2, w: cardW - 0.2, h: 0.4,
    fontSize: 28, fontFace: "Arial Black", color: C.chartSolar,
    bold: true, align: "left", valign: "middle"
  });
  slide.addText("~21% of renewable electricity | Fastest-growing source | Dramatic growth since 2010 driven by falling costs and policy support", {
    x: cardX + 0.1, y: 3.6, w: cardW - 0.2, h: 0.6,
    fontSize: 11, fontFace: "Calibri", color: C.black,
    align: "left", valign: "top"
  });

  // Bottom insight
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 4.45, w: cardW, h: 0.5,
    fill: { color: C.secondary }
  });
  slide.addText("Combined, wind + solar now nearly match hydropower output", {
    x: cardX + 0.1, y: 4.45, w: cardW - 0.2, h: 0.5,
    fontSize: 12, fontFace: "Calibri", color: C.white,
    bold: true, align: "center", valign: "middle"
  });

  addFooter(slide, "Source: Our World in Data – Renewable Energy");
  addSlideNumber(slide, 7);
}

// ============================================================
// SLIDE 8: Regional Disparities / Access Gap
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: C.primary }
  });

  slide.addText("Stark Regional Gaps: Sub-Saharan Africa Lags While Scandinavia and Latin America Lead", {
    x: 0.5, y: 0.25, w: 9.0, h: 0.7,
    fontSize: 24, fontFace: "Arial Black", color: C.dark,
    bold: true, align: "left", valign: "middle"
  });

  // Map on left
  slide.addImage({
    path: "/app/benchmark/assets/figure_3.jpg",
    x: 0.5, y: 1.1, w: 4.8, h: 3.4,
    sizing: { type: "contain", w: 4.8, h: 3.4 }
  });
  slide.addText("Share of electricity from hydropower by country, 2025", {
    x: 0.5, y: 4.55, w: 4.8, h: 0.2,
    fontSize: 10, fontFace: "Calibri", color: C.gray,
    align: "center", valign: "middle"
  });

  // Right side: regional breakdown
  const rx = 5.6;

  // Leaders
  slide.addShape(pres.shapes.RECTANGLE, {
    x: rx, y: 1.1, w: 4.0, h: 1.3,
    fill: { color: C.light }
  });
  slide.addText("LEADERS", {
    x: rx + 0.1, y: 1.15, w: 3.8, h: 0.25,
    fontSize: 12, fontFace: "Arial Black", color: C.primary,
    bold: true, align: "left", valign: "middle"
  });
  slide.addText("Scandinavia, Brazil, and Canada benefit from abundant hydropower (65–98% renewable electricity). Denmark and Germany have invested heavily in wind and solar.", {
    x: rx + 0.1, y: 1.4, w: 3.8, h: 0.9,
    fontSize: 11, fontFace: "Calibri", color: C.black,
    align: "left", valign: "top"
  });

  // Laggards
  slide.addShape(pres.shapes.RECTANGLE, {
